g={modelId=string,apiKeyArn=string,maxTokens=integer,temperature=float,topP=float,apiFormat=string},geminiModelConfig={modelId=string,apiKeyArn=string,maxTokens=integer,temperature=float,topP=float,topK=integer},liteLlmModelConfig={modelId=string,apiKeyArn=string,apiBase=string,maxTokens=integer,temperature=float,topP=float} JSON Syntax: { "bedrockModelConfig": { "modelId": "string", "maxTokens": integer, "temperature": float, "topP": float, "apiFormat": "converse_stream"|"responses"|"chat_completions", "additionalParams": {...} }, "openAiModelConfig": { "modelId": "string", "apiKeyArn": "string", "maxTokens": integer, "temperature": float, "topP": float, "apiFormat": "chat_completions"|"responses", "additionalParams": {...} }, "geminiModelConfig": { "modelId": "string", "apiKeyArn": "string", "maxTokens": integer, "temperature": float, "topP": float, "topK": integer, "additionalParams": {...} }, "liteLlmModelConfig": { "modelId": "string", "apiKeyArn": "string", "apiBase": "string", "maxTokens": integer, "temperature": float, "topP": float, "additionalParams": {...} } }
